from collections import deque
from test.support import NEVER_EQ

def _t():
    values = (float('nan'), 1, None, 'abc', NEVER_EQ)
    constructors = (list, tuple, dict.fromkeys, set, frozenset, deque)
    for constructor in constructors:
        container = constructor(values)
        for elem in container:
            assert elem in container, ('assertIn', elem, container)
        assert container == constructor(values), ('assertTrue', container == constructor(values))
        assert container == container, ('assertTrue', container == container)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

def _t():

    class ByContains(object):

        def __contains__(self, other):
            return False
    c = ByContains()

    class BlockContains(ByContains):
        """Is not a container

            This class is a perfectly good iterable (as tested by
            list(bc)), as well as inheriting from a perfectly good
            container, but __contains__ = None prevents the usual
            fallback to iteration in the container protocol. That
            is, normally, 0 in bc would fall back to the equivalent
            of any(x==0 for x in bc), but here it's blocked from
            doing so.
            """

        def __iter__(self):
            while False:
                yield None
        __contains__ = None
    bc = BlockContains()
    assert not 0 in c, ('assertFalse', 0 in c)
    assert not 0 in list(bc), ('assertFalse', 0 in list(bc))
    try:
        (lambda: 0 in bc)()
    except TypeError:
        pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
